function sumCounts(values) {
  let total = 0;
  for (const value of values) {
    if (!Number.isSafeInteger(value) || value < 0) throw new Error('invalid count');
    total += value;
    if (!Number.isSafeInteger(total)) throw new Error('overflow');
  }
  return total;
}

