function parseSimpleCsv(text) {
  if (text.includes('"')) throw new Error('quotes unsupported');
  const rows = text.split(/\r?\n/).filter(row => row.trim() !== '').map(row => row.split(',').map(cell => cell.trim()));
  if (rows.some(row => row.length !== rows[0].length)) throw new Error('ragged rows');
  return rows;
}

