def usage_status(usage):
    unknown = {'status': 'UNKNOWN', 'input_tokens': None, 'output_tokens': None}
    if usage is None or 'input_tokens' not in usage or 'output_tokens' not in usage:
        return unknown
    if any(type(usage[key]) is not int or usage[key] < 0 for key in ('input_tokens', 'output_tokens')):
        raise ValueError('invalid usage')
    return {'status': 'VERIFIED', 'input_tokens': usage['input_tokens'], 'output_tokens': usage['output_tokens']}
